def process_input_and_find_key() -> int:
    n = int(input())
    cs = {}
    for i in range(n):
        a, c = map(int, input().split())
        if c in cs:
            cs[c].append(a)
        else:
            cs[c] = [a]

    max_min_deliciousness = 0
    best_color = -1
    for k in cs:
        m = min(cs[k])
        if m > max_min_deliciousness:
            best_color = k
            max_min_deliciousness = m
    return best_color
